<template>
  <div class="account-page"><div class="account-heading"><p class="eyebrow">ACCOUNT</p><h1>我的账号</h1><p>管理登录信息，项目与生成记录保留在你的账号下。</p></div><div class="account-grid"><section class="card account-info"><div class="profile-avatar">{{ (user?.displayName || user?.username || '我').slice(0, 1) }}</div><h2 :title="user?.displayName || user?.username">{{ user?.displayName || user?.username }}</h2><p :title="user?.username">@{{ user?.username }}</p><span class="tag">{{ user?.role === 'admin' ? '管理员' : '创作者' }}</span><NuxtLink v-if="user?.role === 'admin'" to="/admin" class="btn">进入管理后台<ArrowUpRight :size="14" /></NuxtLink></section><section class="card password-card"><h2>修改密码</h2><p>请使用你自己记得住的独立密码。</p><form @submit.prevent="save"><label>当前密码<input v-model="current" type="password" class="input" autocomplete="current-password" required /></label><label>新密码<input v-model="password" type="password" class="input" autocomplete="new-password" required placeholder="输入新密码" /></label><label>再次输入新密码<input v-model="confirm" type="password" class="input" autocomplete="new-password" required /></label><p v-if="error" class="error-text" role="alert">{{ error }}</p><button class="btn btn-primary" :disabled="busy"><Loader2 v-if="busy" :size="14" class="animate-spin" />{{ busy ? '正在保存…' : '更新密码' }}</button></form></section></div></div>
</template>
<script setup>
import { computed, ref } from 'vue'
import { ArrowUpRight, Loader2 } from 'lucide-vue-next'
import { toast } from 'vue-sonner'
import { platformSession, changePlatformPassword } from '~/utils/platform-session'
const user = computed(() => platformSession.user), current = ref(''), password = ref(''), confirm = ref(''), error = ref(''), busy = ref(false)
async function save() { error.value = ''; if (busy.value) return; if (current.value === '' || password.value === '') { error.value = '请输入当前密码和新密码。'; return } if (password.value !== confirm.value) { error.value = '两次输入的新密码不一致。'; return } busy.value = true; try { await changePlatformPassword(current.value, password.value); current.value = ''; password.value = ''; confirm.value = ''; toast.success('密码已更新') } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<style scoped>
.account-page{width:100%;min-height:0;overflow:auto;flex:1;max-width:1020px;margin:0 auto;padding:40px 28px}.account-heading{margin-bottom:28px}.eyebrow{font-size:10px;letter-spacing:.16em;color:var(--accent-text);font-weight:700;margin-bottom:10px}.account-heading h1{font-size:27px;margin-bottom:8px}.account-heading>p:last-child{font-size:13px;color:var(--text-3)}.account-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px;min-width:0}.account-info,.password-card{padding:28px;min-width:0;max-width:100%}.account-info{display:flex;align-items:center;flex-direction:column;gap:13px;height:max-content}.profile-avatar{height:65px;width:65px;display:grid;place-items:center;background:var(--accent-bg);color:var(--accent-text);font-size:25px;border-radius:21px;margin:4px 0 8px}.account-info h2,.account-info>p{width:100%;max-width:100%;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-info h2,.password-card h2{font-size:17px}.account-info p,.password-card>p{font-size:12px;color:var(--text-3)}.account-info .btn{margin-top:10px;gap:8px}.password-card form{display:grid;gap:17px;margin-top:24px}.password-card label{display:grid;gap:9px;font-size:12px;color:var(--text-2)}.password-card .btn{justify-self:start}.error-text{font-size:12px;color:var(--error)}@media(max-width:700px){.account-grid{grid-template-columns:minmax(0,1fr)}.account-page{padding:24px 16px}}
</style>
